CustomField.formula:
IF(
  TEXT($User.LanguageLocaleKey) = "zh_TW",
  /* 中文文案 */
  IF(
    ISBLANK(Status_Code__c),
    "",
    IF(
      Status_Code__c = 200,
      "成功",
      "失敗"
    )
  ),
  /* 英文文案 */
  IF(
    ISBLANK(Status_Code__c),
    "",
    IF(
      Status_Code__c = 200,
      "Success",
      "Fail"
    )
  )
)
